#!/usr/bin/env node
/**
 * knowledge/tools/bundle/build-bundle.mjs — make the pack downloadable.
 *
 *   node knowledge/tools/bundle/build-bundle.mjs
 *   node knowledge/tools/bundle/build-bundle.mjs --verify
 *
 * Exit 0 built (or --verify clean) · 1 the bundle is not self-sufficient · 2 usage.
 *
 * A tracked `knowledge/` directory is not a published pack. Without an archive,
 * "the plugin consumes GraphCompose's knowledge" quietly means "the plugin needs
 * a GraphCompose checkout on the machine" — which is the offline problem this
 * work exists to remove, restated rather than solved.
 *
 * So the bundle carries a **query CLI of its own**. That is not convenience: the
 * acceptance test is that it answers on a machine with no GraphCompose source,
 * and without a bundled `--exists` / `--task` there would be nothing on that
 * machine to run the test *with*, so "self-sufficient" would be asserted instead
 * of demonstrated.
 *
 * Checksums are at two levels, and the outer one lives outside:
 *
 *   <bundle>.zip.sha256      beside the archive — a checksum inside the archive
 *                            it describes verifies nothing, because whatever
 *                            rewrote the archive rewrote it too.
 *   bundle-checksums.json    inside — says WHICH entry is wrong, once the outer
 *                            hash has established that something is.
 */

import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

import { writeZip } from "./lib/zip-write.mjs";
import { openJar } from "../api-surface/lib/zip.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(HERE, "..", "..", "..");
const KNOWLEDGE = path.join(REPO_ROOT, "knowledge");
const OUT_DIR = path.join(REPO_ROOT, "target", "knowledge");
const PROVENANCE = path.join(OUT_DIR, "provenance.json");

const args = process.argv.slice(2);
if (args.some((a) => a === "--help" || a === "-h")) {
  process.stdout.write(
    "usage: node knowledge/tools/bundle/build-bundle.mjs [--verify]\n\n" +
      "  --verify   build, then unpack into a scratch directory with no\n" +
      "             repository around it and query it there\n\n" +
      "exit: 0 ok | 1 not self-sufficient | 2 usage\n",
  );
  process.exit(0);
}
if (args.some((a) => a !== "--verify")) process.exit(2);
const verify = args.includes("--verify");

const sha256 = (buffer) => crypto.createHash("sha256").update(buffer).digest("hex");

/** Files under a directory, as slash-separated names relative to it. */
function filesUnder(root, prefix = "") {
  const out = [];
  for (const entry of fs.readdirSync(root, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) out.push(...filesUnder(path.join(root, entry.name), rel));
    else out.push(rel);
  }
  return out;
}

if (!fs.existsSync(path.join(KNOWLEDGE, "manifest.json"))) {
  process.stderr.write(
    "[build-bundle] no knowledge/manifest.json — generate the pack first:\n" +
      "  node knowledge/tools/api-surface/extract-api.mjs --from-reactor\n",
  );
  process.exit(1);
}

const manifest = JSON.parse(fs.readFileSync(path.join(KNOWLEDGE, "manifest.json"), "utf8"));

// Provenance is generated by the extractor into target/ and is deliberately not
// tracked. The bundle is the one place it belongs *inside*: an archive handed to
// someone else should say which commit produced it, which the version string
// alone cannot do for a SNAPSHOT.
if (!fs.existsSync(PROVENANCE)) {
  process.stderr.write(
    `[build-bundle] no ${path.relative(REPO_ROOT, PROVENANCE)} — regenerate the pack so it is written:\n` +
      "  node knowledge/tools/api-surface/extract-api.mjs --from-reactor\n",
  );
  process.exit(1);
}
const provenance = JSON.parse(fs.readFileSync(PROVENANCE, "utf8"));
const version = provenance.version;

// --- what goes in ------------------------------------------------------------

const entries = [];
const add = (name, contents) => entries.push([name, contents]);

add("manifest.json", fs.readFileSync(path.join(KNOWLEDGE, "manifest.json")));
add("provenance.json", fs.readFileSync(PROVENANCE));

for (const sub of ["api", "routing", "claims", "proofs"]) {
  const dir = path.join(KNOWLEDGE, sub);
  if (!fs.existsSync(dir)) continue;
  for (const rel of filesUnder(dir)) {
    add(`${sub}/${rel}`, fs.readFileSync(path.join(dir, ...rel.split("/"))));
  }
}

// The CLI, and only what it imports. Shipping the extractor would put a tool
// that needs javap, Maven and a reactor into an archive whose whole point is
// that it works without any of them.
add("bin/query.mjs", fs.readFileSync(path.join(KNOWLEDGE, "tools", "api-query", "api-query.mjs")));

add(
  "README.md",
  Buffer.from(
    `# GraphCompose knowledge pack — ${version}\n\n` +
      "Generated from the compiled classes of the release named above. Nothing\n" +
      "here is hand-written; regenerate rather than edit.\n\n" +
      "## Ask it a question\n\n" +
      "```bash\n" +
      "node bin/query.mjs --exists GraphCompose.DocumentBuilder.pageSize\n" +
      "node bin/query.mjs --task layout.two-columns\n" +
      "node bin/query.mjs --tasks\n" +
      "```\n\n" +
      "Exit codes are meant to be branched on: `0` found, `3` nothing matched.\n" +
      "A `3` is a real answer — the symbol does not exist in this version — and\n" +
      "it is the answer that stops an invented call.\n\n" +
      "## What is here\n\n" +
      "| Path | Holds |\n" +
      "| --- | --- |\n" +
      "| `manifest.json` | the stable contract: surfaces and classification rules |\n" +
      "| `provenance.json` | the commit, tree state and artifact digests behind this build |\n" +
      "| `api/` | one document per surface, JSON plus a Markdown view |\n" +
      "| `routing/` | intent to recommended path, alternatives, constraints |\n" +
      "| `claims/` | which documentation page asserts which symbol or behaviour |\n" +
      "| `bundle-checksums.json` | SHA-256 per file in this archive |\n\n" +
      "The archive's own checksum is published *beside* it as\n" +
      "`graph-compose-knowledge-${version}.zip.sha256`; a checksum stored inside\n" +
      "an archive cannot vouch for it.\n",
    "utf8",
  ),
);

// Per-file digests, added last so it covers everything before it.
const checksums = {
  schemaVersion: 1,
  version,
  note:
    "SHA-256 per bundled file. Tells you WHICH entry is wrong once the archive's " +
    "own checksum, published beside it, has told you that something is.",
  files: Object.fromEntries(entries.map(([name, contents]) => [name, sha256(contents)])),
};
add("bundle-checksums.json", Buffer.from(`${JSON.stringify(checksums, null, 2)}\n`, "utf8"));

// --- write -------------------------------------------------------------------

const archive = writeZip(entries);
const stem = `graph-compose-knowledge-${version}`;
fs.mkdirSync(OUT_DIR, { recursive: true });

const zipPath = path.join(OUT_DIR, `${stem}.zip`);
const sumPath = `${zipPath}.sha256`;
fs.writeFileSync(zipPath, archive);
fs.writeFileSync(sumPath, `${sha256(archive)}  ${stem}.zip\n`, "utf8");

// --- prove it can be read ----------------------------------------------------

// Round-tripped through the reader this repository already trusts, rather than
// asserted about bytes: if `zip.mjs` cannot open it, neither can anything else
// that opens a jar, and the writer is new code.
const reopened = openJar(zipPath);
const missing = entries.map(([name]) => name).filter((name) => !reopened.names.includes(name));
if (missing.length) {
  process.stderr.write(`[build-bundle] archive does not read back: missing ${missing.join(", ")}\n`);
  process.exit(1);
}
for (const [name, contents] of entries) {
  if (!reopened.read(name).equals(contents)) {
    process.stderr.write(`[build-bundle] archive does not read back: ${name} differs\n`);
    process.exit(1);
  }
}

process.stdout.write(
  `[build-bundle] ${stem}.zip  ${(archive.length / 1024).toFixed(0)} KiB  ${entries.length} files\n` +
    `  ${path.relative(REPO_ROOT, zipPath)}\n` +
    `  ${path.relative(REPO_ROOT, sumPath)}\n` +
    `  round-trips through zip.mjs\n`,
);

if (!verify) process.exit(0);

// --- self-sufficiency --------------------------------------------------------

// Unpacked well away from the repository, so nothing here can be answered by a
// file that happens to be lying around next to it.
const scratch = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), "gc-bundle-"));
for (const name of reopened.names) {
  const target = path.join(scratch, ...name.split("/"));
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, reopened.read(name));
}

const run = (...cliArgs) =>
  spawnSync(process.execPath, [path.join(scratch, "bin", "query.mjs"), ...cliArgs], { encoding: "utf8" });

const checks = [
  ["--exists GraphCompose.DocumentBuilder.pageSize", run("--exists", "GraphCompose.DocumentBuilder.pageSize"), 0],
  ["--task layout.two-columns", run("--task", "layout.two-columns"), 0],
  ["--exists TableBuilder.noSuchMethod", run("--exists", "TableBuilder.noSuchMethod"), 3],
];

let failed = 0;
process.stdout.write(`\n[build-bundle] standalone, unpacked at ${scratch}\n`);
for (const [label, result, expected] of checks) {
  const ok = result.status === expected;
  if (!ok) failed += 1;
  process.stdout.write(
    `  ${ok ? "ok  " : "FAIL"}  exit ${result.status} (want ${expected})  ${label}\n` +
      (ok ? "" : `        ${(result.stderr || result.stdout || "").trim().split("\n")[0]}\n`),
  );
}

fs.rmSync(scratch, { recursive: true, force: true });

if (failed) {
  process.stderr.write("\n[build-bundle] the bundle is not self-sufficient\n");
  process.exit(1);
}
process.stdout.write("  the bundle answers with no repository present\n");
